(* [comment removed for export] *)
Lemma RWp_read_post : forall (C : rsc) (w : rsw) (k : Z),
  rs_static C -> RWp H C w -> w_FB w <> FB_empty -> 0 < fb_begin (w_FB w) -> 0 <= k <= zlength (w_sds w) ->
  RWp H C (w_after_read w k).
Proof.
  intros C w k STC RP NE BP KR.
  destruct C as [P N lo B0 stb implb A LBin pad7 pad2 j13 j32a j8a j32b j8b mb m0 mo0 gp tp s10 s11 F fc].
  destruct w as [d PB FBB FB fds Fs sds nr]. destruct d as [c S L1 ns ls em h u es insz g rdi LBn st errv].
  unfold w_after_read, fb_commit, RWp, rs_static in *. cbn_w_all.
  destruct STC as (P0 & PBB & BHI & AL16 & CEIL & IMG & LO & NR26 & (p7 & INS) & RBS & INA & TP).
  destruct RP as (PCOK & OWN & MOWN & HOWN & EH & ESH & DFB & HST & U01 & CAP & LES & INZ & LEN1 & HDJ & HL8 & SK62
                  & AOWN & PERM & FOK & FRL & FRB & FRT & FRM & FRF & DJL & DJB & DJT & DJM & STRM & SZS & NRK & CPM & BY & CN & IZ).
  unfold fb_cap in *. cbn [fb_begin fb_in fb_out fb_last fb_end] in *.
  assert (ZL : zlength (fds ++ firstn (Z.to_nat k) sds) + zlength (skipn (Z.to_nat k) sds) = zlength fds + zlength sds).
  { rewrite zlength_app, zlength_firstn, zlength_skipn; unfold zlength in *; lia. }
  assert (NE' : {| fb_begin := fb_begin FB; fb_in := fb_in FB; fb_out := fb_out FB + k; fb_last := fb_last FB; fb_end := fb_end FB |} <> FB_empty).
  { intros E. pose proof (f_equal fb_begin E) as K. cbn in K. lia. }
  split; [exact PCOK|]. split; [exact OWN|]. split; [exact MOWN|]. split; [exact HOWN|]. split; [exact EH|]. split; [exact ESH|]. split; [exact DFB|].
  split; [exact HST|]. split; [exact U01|]. split; [exact CAP|]. split; [exact LES|]. split; [exact INZ|]. split; [exact LEN1|]. split; [exact HDJ|].
  split; [exact HL8|]. split; [exact SK62|]. split; [exact AOWN|]. split; [exact PERM|].
  split. { destruct FOK as [[K _] | (_ & pf & ->)]; [exfalso; exact (NE K)|]. right. split; [exact NE'|]. exists pf. reflexivity. }
  split; [exact FRL|]. split; [exact FRB|]. split; [exact FRT|]. split; [exact FRM|].
  split; [intros _; exact (FRF NE)|]. split; [intros _; exact (DJL NE)|]. split; [intros _; exact (DJB NE)|]. split; [intros _; exact (DJT NE)|]. split; [intros _; exact (DJM NE)|].
  split.
  { destruct STRM as [[N0 EFs] | (N1 & SA & SE & SD)].
    - left. split; [exact N0|]. replace (zlength sds =? 0) with true by (symmetry; apply Z.eqb_eq; unfold zlength in *; lia). exact EFs.
    - right. split; [exact N1|]. destruct (zlength sds =? 0); [split; [exact SA | split; [exact SE | exact SD]]|].
      pose proof (fb_consume_shape Fs k) as (CB1 & CB2 & _). rewrite CB1, CB2. split; [exact SA | split; [exact SE | exact SD]]. }
  rewrite ZL. split; [exact SZS|]. split; [lia|]. split; [exact CPM|]. split; [exact BY|]. split; [exact CN|]. exact IZ.
Qed.

(* [comment removed for export] *)
Lemma RWp_eof_post : forall (C : rsc) (w : rsw),
  RWp H C w -> RWp H C (w_after_eof w).
Proof.
  intros C w RP.
  destruct C as [P N lo B0 stb implb A LBin pad7 pad2 j13 j32a j8a j32b j8b mb m0 mo0 gp tp s10 s11 F fc].
  destruct w as [d PB FBB FB fds Fs sds nr]. destruct d as [c S L1 ns ls em h u es insz g rdi LBn st errv].
  unfold w_after_eof, pst_eof, RWp in *. cbn_w_all.
  destruct RP as (PCOK & OWN & MOWN & HOWN & EH & ESH & DFB & HST & U01 & CAP & LES & INZ & LEN1 & HDJ & HL8 & SK62
                  & AOWN & PERM & FOK & FRL & FRB & FRT & FRM & FRF & DJL & DJB & DJT & DJM & STRM & SZS & NRK & CPM & BY & CN & IZ).
  pose proof (rs_eof_facts c g PCOK) as (PCOK' & _ & _ & _).
  destruct (rs_eof_c_cases c) as [EC | EC]; rewrite EC in *.
  { repeat (split; [assumption|]). exact IZ. }
  unfold pc_set_state in *. cbn [pc_state pc_hlim pc_len pc_skip] in *.
  split; [exact PCOK'|]. split; [exact OWN|]. split; [exact MOWN|]. split; [exact HOWN|]. split; [exact EH|]. split; [exact ESH|]. split; [exact DFB|].
  split; [intros K; exfalso; clear - K; lia|]. split; [exact U01|]. split; [exact CAP|]. split; [exact LES|]. split; [exact INZ|].
  split; [intros K; exfalso; clear - K; lia|]. split; [exact HDJ|]. split; [intros K; exfalso; clear - K; lia|]. split; [exact SK62|].
  split; [exact AOWN|]. split; [exact PERM|]. split; [exact FOK|].
  split; [exact FRL|]. split; [exact FRB|]. split; [exact FRT|]. split; [exact FRM|].
  split; [exact FRF|]. split; [exact DJL|]. split; [exact DJB|]. split; [exact DJT|]. split; [exact DJM|].
  split; [exact STRM|]. split; [exact SZS|]. split; [exact NRK|]. split; [exact CPM|].
  replace (11 <=? 9) with false by reflexivity. replace (11 <=? 1) with false by reflexivity. cbv iota.
  set (s34 := if pc_state c <=? 9 then 34 else 0) in *. set (s8 := if pc_state c <=? 1 then 8 else 0) in *. set (s2 := if pc_state c <=? 9 then 2 else 0) in *.
  assert (0 <= s34) by (subst s34; destruct (pc_state c <=? 9); lia).
  assert (0 <= s8) by (subst s8; destruct (pc_state c <=? 1); lia).
  assert (0 <= s2) by (subst s2; destruct (pc_state c <=? 9); lia).
  split; [clear - BY H0; lia|]. split; [clear - CN H1 H2; lia|]. exact IZ.
Qed.

