Definition rs_at_cmp (C : rsc) (sp : word) (s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra : word) (fr0 : list word) (M0 : Z) (w : rsw) (eof : bool) (cf : config) : Prop :=
  exists (rax t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s6x t3 t4 t5 t6 : word) (m : mem) (tot k : Z) (j8 : list byte) (t1c optc : list cell),
    cfg_ms cf = MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -144)) (c_gp C) (c_tp C) t0 t1 t2 (wz tot) (wz (c_P C + O_H_EC)) a0 a1 a2 a3 a4 a5 a6 a7
                     (wz (c_P C)) (wz (c_P C + O_H_FB)) (wz (c_P C + O_H_STREAM)) (wz k) s6x (wz G_MISC_CAT_INST) (wz G_SYSTEM_CAT_INST) (wz CAT_ID_SYSGEN_SHR1)
                     (c_s10 C) (c_s11 C) t3 t4 t5 t6)
                (c_F C) (Z_to_bv 64 RS_CMP) (c_fc C) None m (seg_rom rsegs)
    /\ pc_state (ps_c (w_d w)) <> 11
    /\ hs_KREL H (ps_st (w_d w)) (cfg_model cf) /\ hs_MPRES H (c_mo0 C) (cfg_model cf)
    /\ RWm H C w (if eof then EC_ts_eof else EC_clear) m /\ RWp H C w /\ stk rsegs m (c_lo C) (bv_unsigned sp + -144)
    /\ rs_frames m sp j8 t1c optc s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra fr0
    /\ xpres (c_LBin C) (c_P C) (sro_X (c_P C) (c_stb C)) (c_m0 C) m
    /\ 0 <= tot /\ tot + zlength (w_fds w) + zlength (w_sds w) <= c_N C
    /\ wM (c_N C) w <= M0
    /\ (if eof then w_sds w = [] /\ k = 0
        else 1 <= k /\ k <= fb_size (w_FB w) /\ fb_in (w_FB w) <= fb_out (w_FB w) /\ wM (c_N C) w < M0 /\ w_nr w <= c_N C - zlength (w_sds w)).
