(* [comment removed for export] *)
Lemma rs_read_B2 : forall (C : rsc) (sp : word) (s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra : word) (fr0 : list word) (M0 : Z) (w : rsw) (eof : bool) (cf : config),
  rs_static C -> bv_unsigned sp = c_P C - 64 ->
  rs_at_cmp C sp s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra fr0 M0 w eof cf ->
  hs_SR H (fun cf' => rs_done H C sp s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra fr0 M0 cf'
                      \/ exists M1 w', M1 < M0 /\ rs_at_put H C sp s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra fr0 M1 w' cf') cf.
Proof.
  intros C sp s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra fr0 M0 w eof cf STC SPE AT.
  pose proof STC as STC0.
  destruct C as [P N lo B stb implb A LBin pad7 pad2 j13 j32a j8a j32b j8b mb m0 mo0 gp tp s10 s11 F fc].
  destruct w as [d PB FBB FB fds Fs sds nr]. destruct d as [c S L ns ls em h u es insz g rdi LBn st errv].
  destruct cf as [ms mo]. unfold rs_at_cmp, rs_frames, RWm, rs_static in *. cbn_w_all. cbn [cfg_ms cfg_model] in AT.
  destruct STC as (P0 & PBB & BHI & AL16 & CEIL & IMG & LO & NR26 & (p7 & INS) & RBS & INA & TP).
  destruct AT as (rax & t0 & t1 & t2 & a0 & a1 & a2 & a3 & a4 & a5 & a6 & a7 & s6x & t3 & t4 & t5 & t6 & m & tot & k & j8 & t1c & optc
                  & -> & NS11 & KREL & MP & RM & RP & ST & (FRM & FRhi & FR0 & LFR0) & XP0 & TOT0 & TOT & WM0 & CASE).
  destruct RM as (PC & UW & RDI & J13 & J32a & J8a & J32b & J8b & HC & FTS & MV & FBU & EC & BS & SB & HP & ERR & AUX & MI).
  pose proof RP as RP0. unfold RWp in RP. cbn_w_all.
  destruct RP as (PCOK & OWN & MOWN & HOWN & EH & ESH & DFB & HST & U01 & CAP & LES & INZ & LEN1 & HDJ & HL8 & SK62
                  & AOWN & PERM & FOK & FRL & FRB & FRT & FRM_ & FRF & DJL & DJB & DJT & DJM & STRM & SZS & NRK & CPM & BY & CN & IZ).
  assert (LOP : lo + 13136 <= P) by (clear - LO; unfold SRO_STACK, PUT_STACK, IPF_STACK, IPF_FRAME, OTF_STACK, INS_STACK, ROPNEW_STACK, RMALLOC_STACK in LO; lia).
  hcb. pose proof (bv_unsigned_in_range 64 sp) as SPR. unfold bv_modulus in SPR. change (2 ^ Z.of_N 64) with (2^64) in SPR.
  subst tp.
  pose proof (FlatBuf_shape _ _ _ _ _ FBU) as (FS1 & FS2 & FS3 & FS4 & FS5). pose proof (FlatBuf_size _ _ _ _ _ FBU) as FSZ.
  destruct FRM as (F8 & T1 & SZT1 & OPT & SZT2).
  pose proof UW as (FC & HDR & USED & MB & RD & MRG & CBH & CBB & PFT & FI & XS).
  pose proof RBS as (RB1 & RB2 & RB3 & RB4 & RB5). unfold SZ_SPCI_STATE in RB4, RB5.
  assert (HB0 : forall b, In b LBin -> blk_addr b + blk_size b <= hceil).
  { intros b Hb. destruct (hh_blocks H HH _ _ _ b HP ltac:(apply in_or_app; right; exact Hb)) as (_ & _ & _ & X4 & _). exact X4. }
  unfold O_H_EC, O_H_FB, O_H_STREAM. unfold wz.
  destruct eof.
  - (* [comment removed for export] *)
    destruct CASE as [Esds K0]. subst sds k. cbv iota in EC.
    pose proof rs_eof as RE. unfold rs_eof_stmt, rs_eof_post, RS_CMP, O_H_EC, O_H_FB, O_H_STREAM in RE. unfold wz in RE.
    eapply (hh_evt H HH); [exact KREL | |].
    { eapply (RE rax ra sp gp _ t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s6x s10 s11 s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v t3 t4 t5 t6
                 F fc m lo P tot c pad7 pad2 g j8 t1c optc); try eassumption.
      all: clear - SPE SPR LOP LO P0 PBB BHI CEIL IMG TOT TOT0 NR26; unfold SRO_STACK, zlength in *; cbn [length] in *; lia. }
    clear RE. cbv beta.
    intros ms1 (u0 & u1 & u2 & b1 & b2 & b3 & b4 & b5 & b6 & b7 & u3 & u4 & u5 & u6 & m1 & -> & MU1 & WM1 & MI1 & ST1 & PC1 & EC1 & HC1 & XS1).
    unfold rs_W5, G_HTTP_CAT in MU1.
    left. unfold rs_done. cbn [cfg_ms cfg_model].
    set (C := mkC P N lo B stb implb A LBin pad7 pad2 j13 j32a j8a j32b j8b mb m0 mo0 gp (Z_to_bv 64 RATP) s10 s11 F fc) in *.
