Lemma rs_done_mono : forall (C : rsc) (sp : word) (s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra : word) (fr0 : list word) (M1 M0 : Z) (cf : config),
  rs_done H C sp s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra fr0 M1 cf -> M1 <= M0 ->
  rs_done H C sp s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra fr0 M0 cf.
Proof.
  intros C sp s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra fr0 M1 M0 cf D LE. unfold rs_done in *.
  destruct D as (t0 & t1 & t2 & a1 & a2 & a3 & a4 & a5 & a6 & a7 & t3 & t4 & t5 & t6 & m & w & E & tot & D).
  exists t0, t1, t2, a1, a2, a3, a4, a5, a6, a7, t3, t4, t5, t6, m, w, E, tot.
  destruct D as (D1 & D2 & D3 & D4 & D5 & D6 & D7 & D8 & D9 & D10 & D11 & D12 & D13 & D14).
  repeat (split; [assumption|]). split; [clear - D13 LE; lia|].
  intros K1 K2. destruct (D14 K1 K2) as [K3 K4]. split; [clear - K3 LE; lia | exact K4].
Qed.

Lemma rs_read_round : forall (C : rsc) (sp : word) (s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra : word) (fr0 : list word) (M0 : Z) (w : rsw) (cf : config),
